// Find three free slots — Bright Smile Dental
// Input:  "Read the tool call" + "Read the day's bookings"
// Output: { results: [ { toolCallId, result } ] }

const TZ = 'America/Denver';
const SLOT_MINUTES = 30;
const BUFFER_MINUTES = 15;
const MAX_OPTIONS = 3;

// Opening hours, keyed by Luxon weekday: 1 = Monday ... 7 = Sunday.
// null means closed. This is the ONLY place hours are defined.
const HOURS = {
  1: { open: 9, close: 17 },
  2: { open: 9, close: 17 },
  3: { open: 9, close: 17 },
  4: { open: 9, close: 17 },
  5: { open: 9, close: 17 },
  6: { open: 9, close: 16 },   // Saturday — confirmed 9am to 4pm
  7: null                       // Sunday — closed
};

const tc = $('Read the tool call').first().json;
const toolCallId = tc.toolCallId;
const requested = DateTime.fromISO(tc.requestedIso, { zone: TZ });

const reply = (sentence) => [
  { json: { results: [{ toolCallId, result: sentence }] } }
];

// --- Guard 1: no usable date -------------------------------------------
if (!requested.isValid) {
  return reply('I did not catch which day you meant. Which day would suit you?');
}

const now = DateTime.now().setZone(TZ);
const todayStart = now.startOf('day');

// --- Guard 2: the date has already passed ------------------------------
if (requested < todayStart) {
  return reply('That date has already passed. Which upcoming day would suit you?');
}

// --- Guard 3: the clinic is closed that day ----------------------------
const hours = HOURS[requested.weekday];
if (!hours) {
  return reply('We are closed on ' + requested.toFormat('cccc') + 's. Which other day suits you?');
}

// --- Build the busy list from the calendar -----------------------------
const events = $('Read the day\'s bookings').all().map(i => i.json);
const busy = [];

for (const ev of events) {
  if (!ev || ev.status === 'cancelled') continue;

  const s = ev.start || {};
  const e = ev.end || {};
  let startAt, endAt;

  if (s.dateTime) {
    startAt = DateTime.fromISO(s.dateTime, { zone: TZ });
    endAt = DateTime.fromISO(e.dateTime, { zone: TZ });
  } else if (s.date) {
    // All-day event: blocks the entire working day
    startAt = requested.set({ hour: hours.open, minute: 0 }).startOf('minute');
    endAt = requested.set({ hour: hours.close, minute: 0 }).startOf('minute');
  } else {
    continue;
  }

  if (!startAt.isValid || !endAt.isValid) continue;

  busy.push({
    start: startAt.minus({ minutes: BUFFER_MINUTES }),
    end: endAt.plus({ minutes: BUFFER_MINUTES })
  });
}

// --- Walk the day in slots ---------------------------------------------
const dayOpen = requested.set({ hour: hours.open, minute: 0, second: 0, millisecond: 0 });
const dayClose = requested.set({ hour: hours.close, minute: 0, second: 0, millisecond: 0 });

const free = [];
for (let s = dayOpen; s < dayClose; s = s.plus({ minutes: SLOT_MINUTES })) {
  const e = s.plus({ minutes: SLOT_MINUTES });
  if (e > dayClose) break;
  if (s <= now) continue;                       // never offer a time already gone
  const clash = busy.some(b => s < b.end && e > b.start);
  if (!clash) free.push(s);
}

if (free.length === 0) {
  return reply('I have nothing left that day. Would another day work?');
}

// Prefer slots at or after the time they asked for; fall back to the whole day
const atOrAfter = free.filter(s => s >= requested);
const usedFallback = atOrAfter.length === 0;
const chosen = (usedFallback ? free : atOrAfter).slice(0, MAX_OPTIONS);

// --- Say it like a person ---------------------------------------------
const ordinal = (n) => {
  const r10 = n % 10, r100 = n % 100;
  if (r10 === 1 && r100 !== 11) return n + 'st';
  if (r10 === 2 && r100 !== 12) return n + 'nd';
  if (r10 === 3 && r100 !== 13) return n + 'rd';
  return n + 'th';
};

const isNoon = (d) => d.hour === 12 && d.minute === 0;
const clock  = (d) => (d.minute === 0 ? d.toFormat('h') : d.toFormat('h:mm'));
const span   = (d) => (d.hour < 12 ? 'in the morning' : 'in the afternoon');

// Only name morning/afternoon on the last time of each run, so it reads as
// "9, 9:30, or 10 in the morning" rather than repeating it three times.
const parts = [];
chosen.forEach((d, idx) => {
  const next = chosen[idx + 1];
  const lastOfRun = !next || isNoon(next) || span(next) !== span(d);
  if (isNoon(d)) {
    parts.push('12 noon');
  } else {
    parts.push(lastOfRun ? clock(d) + ' ' + span(d) : clock(d));
  }
});

let timeList;
if (parts.length === 1) {
  timeList = parts[0];
} else if (parts.length === 2) {
  timeList = parts[0] + ' or ' + parts[1];
} else {
  timeList = parts.slice(0, -1).join(', ') + ', or ' + parts[parts.length - 1];
}

const dayPhrase = requested.toFormat('cccc') + ' the ' + ordinal(requested.day);

let spoken;
if (usedFallback) {
  spoken = 'I have nothing left at that time, but I do have ' + dayPhrase + ' at ' + timeList + '.';
} else if (chosen.length === 1) {
  spoken = 'I have one time left on ' + dayPhrase + ': ' + timeList + '.';
} else {
  spoken = 'I have ' + dayPhrase + ' at ' + timeList + '.';
}

return reply(spoken);

const call = $json.body.message.toolCalls[0];
const args = call.function["arguments"];

const requested = new Date(args.initialSearchDateTime);

const windowStart = new Date(requested);
windowStart.setHours(0, 0, 0, 0);

const windowEnd = new Date(windowStart);
windowEnd.setDate(windowEnd.getDate() + 1);

return [
  {
    json: {
      toolCallId: call.id,
      toolName: call.function.name,
      requestedIso: args.initialSearchDateTime,
      windowStart: windowStart.toISOString(),
      windowEnd: windowEnd.toISOString()
    }
  }
];

const call = $json.body.message.toolCalls[0];
const args = call.function["arguments"];

const nowIso = new Date().toISOString();

return [
  {
    json: {
      toolCallId: call.id,
      startDateTime: args.startDateTime,
      endDateTime: args.endDateTime,
      clientName: args.clientName,
      phone: args.phone,
      serviceType: args.serviceType,
      summary: args.clientName + ' — ' + args.serviceType,
      description: 'Booked by Ava, the AI receptionist.'
        + '\nCallback number: ' + args.phone
        + '\nService: ' + args.serviceType,

      timestamp: nowIso,
      caller_name: args.clientName,
      reason: args.reason || args.serviceType,
      urgency: args.urgency || 'routine',
      new_or_existing: args.newOrExisting || 'unknown',
      booked_time: args.startDateTime,
      outcome: 'booked'
    }
  }
];

const booking = $('Read the booking request').first().json;

const when = DateTime.fromISO(booking.startDateTime, { zone: 'America/Denver' });

function ordinal(n) {
  if (n > 3 && n < 21) return n + 'th';
  if (n % 10 === 1) return n + 'st';
  if (n % 10 === 2) return n + 'nd';
  if (n % 10 === 3) return n + 'rd';
  return n + 'th';
}

const clock = when.minute === 0 ? when.toFormat('h') : when.toFormat('h:mm');
const partOfDay = when.hour < 12 ? 'in the morning' : 'in the afternoon';

const spoken = 'You are booked in for ' + when.toFormat('cccc')
  + ', ' + when.toFormat('LLLL') + ' ' + ordinal(when.day)
  + ', at ' + clock + ' ' + partOfDay
  + '. You will get a text confirmation shortly.';

return [
  {
    json: {
      results: [
        {
          toolCallId: booking.toolCallId,
          result: spoken
        }
      ]
    }
  }
];

const call = $json.body.message.toolCalls[0];

const spoken = 'I cannot do that part myself, but I can take your number and have the office call you back within the hour.';

return [
  {
    json: {
      results: [
        {
          toolCallId: call.id,
          result: spoken
        }
      ]
    }
  }
];

const call = $json.body.message.toolCalls[0];
const args = call.function["arguments"] || {};

const preferred = [args.preferredDay, args.preferredTime].filter(Boolean).join(' ');

return [{
  json: {
    toolCallId: call.id,
    timestamp: DateTime.now().setZone('America/Denver').toFormat('yyyy-LL-dd HH:mm:ss'),
    caller_name: args.clientName || '',
    phone: String(args.phone || ''),
    reason: args.reason || '',
    urgency: args.urgency || 'routine',
    new_or_existing: args.newOrExisting || '',
    booked_time: preferred ? 'wanted: ' + preferred : '',
    outcome: 'callback_requested'
  }
}];
